{
  "nl": {
    "issue": [
      {
        "text": "保管合同的界定与成立：保管人保管寄存人交付的保管物并返还该物；合同自保管物交付时成立（实践性），当事人另有约定的除外；寄存人到保管人处购物、就餐、住宿并将物品存放在指定场所的，视为保管",
        "rules": ["c888-1", "c888-2", "c890-1"]
      },
      {
        "text": "保管人的义务与责任：出具保管凭证、妥善保管、不得擅自改变保管场所或方法、亲自保管、不得擅自使用、第三人主张权利时的返还与通知、保管不善的赔偿责任及无偿保管人的免责",
        "rules": ["c891-1", "c892-1", "c892-2", "c892-3", "c894-1", "c894-2", "c895-1", "c896-1", "c896-2", "c897-1", "c897-2"]
      },
      {
        "text": "寄存人的告知义务与贵重物品声明义务及其违反后果",
        "rules": ["c893-1", "c893-2", "c893-3", "c898-1", "c898-2"]
      },
      {
        "text": "保管物的领取与返还：寄存人可随时领取；无期限保管合同中保管人可随时请求领取；期限届满或提前领取时返还原物及孳息；货币及可替代物的返还方式",
        "rules": ["c899-1", "c899-2", "c899-3", "c900-1", "c901-1", "c901-2"]
      }
    ],
    "conditions": [
      {
        "text": "寄存人向保管人交付保管物，且当事人未对合同成立另有约定",
        "rules": ["c890-1"]
      },
      {
        "text": "寄存人到保管人处从事购物、就餐、住宿等活动，并将物品存放在指定场所",
        "rules": ["c888-2"]
      },
      {
        "text": "保管物有瑕疵，或者根据保管物的性质需要采取特殊保管措施",
        "rules": ["c893-1"]
      },
      {
        "text": "寄存人寄存货币、有价证券或者其他贵重物品",
        "rules": ["c898-1"]
      },
      {
        "text": "第三人对保管物主张权利，或者第三人对保管人提起诉讼、对保管物申请扣押",
        "rules": ["c896-1", "c896-2"]
      },
      {
        "text": "保管期内因保管人保管不善造成保管物毁损、灭失",
        "rules": ["c897-1"]
      },
      {
        "text": "当事人对保管期限没有约定或者约定不明确",
        "rules": ["c899-2"]
      },
      {
        "text": "当事人约定保管期限",
        "rules": ["c899-3"]
      },
      {
        "text": "保管期限届满，或者寄存人提前领取保管物",
        "rules": ["c900-1"]
      },
      {
        "text": "保管物为货币，或者为其他可替代物且约定返还相同种类、品质、数量的物品",
        "rules": ["c901-1", "c901-2"]
      }
    ],
    "exceptions": [
      {
        "text": "当事人另有约定或者另有交易习惯的，不视为保管",
        "rules": ["c888-2"]
      },
      {
        "text": "当事人对合同成立另有约定的，不按交付时成立",
        "rules": ["c890-1"]
      },
      {
        "text": "另有交易习惯的，保管人无须出具保管凭证",
        "rules": ["c891-1"]
      },
      {
        "text": "紧急情况或者为维护寄存人利益的，保管人可以改变保管场所或者方法",
        "rules": ["c892-3"]
      },
      {
        "text": "寄存人未告知致保管物受损的，保管人不承担赔偿责任；但保管人知道或者应当知道且未采取补救措施的，寄存人仍应赔偿保管人的损失",
        "rules": ["c893-2", "c893-3"]
      },
      {
        "text": "当事人另有约定的，保管人可以将保管物转交第三人保管，也可以使用或者许可第三人使用保管物",
        "rules": ["c894-1", "c895-1"]
      },
      {
        "text": "依法对保管物采取保全或者执行措施的，保管人不负向寄存人返还的义务",
        "rules": ["c896-1"]
      },
      {
        "text": "无偿保管人证明自己没有故意或者重大过失的，不承担赔偿责任",
        "rules": ["c897-2"]
      },
      {
        "text": "寄存人未声明贵重物品的，该物品毁损、灭失后保管人可以按照一般物品予以赔偿",
        "rules": ["c898-2"]
      },
      {
        "text": "约定保管期限的，保管人无特别事由不得请求寄存人提前领取保管物",
        "rules": ["c899-3"]
      }
    ],
    "effects": [
      {
        "text": "保管人负有保管保管物并返还该物的义务",
        "rules": ["c888-1"]
      },
      {
        "text": "保管合同成立（交付时成立；在经营场所存放物品的视为保管）",
        "rules": ["c890-1", "c888-2"]
      },
      {
        "text": "保管人应当出具保管凭证",
        "rules": ["c891-1"]
      },
      {
        "text": "保管人应当妥善保管保管物；当事人可以约定保管场所或者方法",
        "rules": ["c892-1", "c892-2"]
      },
      {
        "text": "寄存人应当将保管物瑕疵或者特殊保管需要告知保管人",
        "rules": ["c893-1"]
      },
      {
        "text": "保管人不得擅自将保管物转交第三人保管、不得使用或者许可第三人使用保管物；违反转交造成损失的应当承担赔偿责任",
        "rules": ["c894-1", "c894-2", "c895-1"]
      },
      {
        "text": "第三人主张权利时保管人应向寄存人返还保管物；第三人起诉或者申请扣押时应及时通知寄存人",
        "rules": ["c896-1", "c896-2"]
      },
      {
        "text": "保管不善致保管物毁损、灭失的，保管人应当承担赔偿责任",
        "rules": ["c897-1"]
      },
      {
        "text": "寄存人应当声明贵重物品并由保管人验收或封存；未声明的按一般物品赔偿",
        "rules": ["c898-1", "c898-2"]
      },
      {
        "text": "寄存人可以随时领取保管物；无期限保管合同中保管人可以随时请求寄存人领取",
        "rules": ["c899-1", "c899-2"]
      },
      {
        "text": "保管人应当将原物及其孳息归还寄存人",
        "rules": ["c900-1"]
      },
      {
        "text": "保管货币或者可替代物的，可以返还相同种类、数量（品质）的货币或者物品",
        "rules": ["c901-1", "c901-2"]
      }
    ],
    "priority": [
      {
        "text": "无偿保管人证明无故意或者重大过失的免责，优先于保管不善的赔偿责任",
        "rules": ["c897-2"]
      },
      {
        "text": "寄存人未告知致保管物受损的，保管人不负赔偿责任，优先于一般保管不善责任",
        "rules": ["c893-2"]
      },
      {
        "text": "寄存人未声明贵重物品的按一般物品赔偿，优先于按实际价值赔偿",
        "rules": ["c898-2"]
      },
      {
        "text": "当事人另有约定优先于不得转交第三人保管、不得使用保管物的禁止性规定",
        "rules": ["c894-1", "c895-1"]
      }
    ],
    "distinguish": [
      {
        "text": "笔记中寄存人负担必要费用、支付保管费以及保管人对保管物享有留置权的规则，规定于第889条、第903条，本行未挂载，故不列入",
        "rules": []
      },
      {
        "text": "仓储合同为有偿、诺成、形式要求更高的商事合同，保管合同多为无偿、实践性、不要式；委托合同以处理事务为标的，租赁合同以转移使用收益为目的，均不同于保管合同",
        "rules": []
      },
      {
        "text": "LEGO 卡片称“保管人应优先通知寄存人、不得擅自返还”，与第896条第1款不符：第三人主张权利时，除依法采取保全或者执行措施外，保管人仍应向寄存人返还；通知义务另由第2款规定",
        "rules": ["c896-1", "c896-2"]
      }
    ]
  },
